function memberId(member){return member.email||member.name}
function allocationsForBill(bill,members){if(Array.isArray(bill?.allocations)&&bill.allocations.length)return bill.allocations;const legacy=bill?.split||'';if(legacy==='50/50'&&members.length){const share=Math.floor(10000/members.length)/100;return members.map((m,i)=>({member:m.name,email:m.email,percent:i===members.length-1?100-share*(members.length-1):share}))}if(legacy.endsWith(' pays all')){const name=legacy.slice(0,-9),member=members.find(m=>m.name===name);return member?[{member:member.name,email:member.email,percent:100}]:[]}return []}
