function billShareForMember(bill,person,members){const amount=Number(bill.amount)||0;if(bill.allocations?.length){return bill.allocations.filter(x=>x.member===person).reduce((sum,x)=>sum+amount*Number(x.percent)/100,0)}if(bill.split==='50/50')return amount/Math.max(members.length,1);if((bill.split||'').endsWith(' pays all'))return bill.split.slice(0,-9)===person?amount:0;if(bill.assignedTo)return bill.assignedTo===person?amount:0;return 0}
