function parseReminderTime(value){const m=(value||'').match(/(\d{1,2}):(\d{2})\s*(AM|PM)/i);if(!m)return '';let h=Number(m[1])%12;if(m[3].toUpperCase()==='PM')h+=12;return `${String(h).padStart(2,'0')}:${m[2]}`}
